CREATE TEMP TABLE history_flag_writes(flag_changed boolean,data_changed boolean); CREATE FUNCTION pg_temp.track_history_flag_writes() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN INSERT INTO history_flag_writes VALUES(OLD.record_eligible IS DISTINCT FROM NEW.record_eligible,(to_jsonb(OLD)-'record_eligible') IS DISTINCT FROM (to_jsonb(NEW)-'record_eligible')); RETURN NULL; END $$; CREATE TRIGGER test_history_flag_writes AFTER UPDATE ON zc_private.record_history_index FOR EACH ROW EXECUTE FUNCTION pg_temp.track_history_flag_writes();
